import requests

def fetch(url="https://example.org/feed/latest.json?limit=10&page=1", extra_params=None):
    if extra_params is None:
        extra_params = {}
    params = {**{"page": 1, "limit": 10}, **extra_params}
    response = requests.get(url, params=params)
    response.raise_for_status()
    return response.json()

print(fetch())
